import * as T from './vendor/three.module.js';
import {LANES,clamp} from './core.js';
import {Railway} from './railway.js';
const colors={mint:0x87c9b1,cream:0xf8edc5,dark:0x193e35,pink:0xf34684,lime:0xd9fd66,orange:0xffa644};
const sphere=new T.SphereGeometry(1,24,16),box=new T.BoxGeometry(1,1,1),cylinder=new T.CylinderGeometry(1,1,1,24),round=new T.CapsuleGeometry(1,1,4,12);
const mats=new Map();
function mat(color,rough=.55,metal=0){const key=`${color}-${rough}-${metal}`;if(!mats.has(key))mats.set(key,new T.MeshStandardMaterial({color,roughness:rough,metalness:metal}));return mats.get(key);}
function mesh(parent,geo,material,position=[0,0,0],scale=[1,1,1]){const m=new T.Mesh(geo,typeof material==='number'?mat(material):material);m.position.set(...position);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function rod(parent,a,b,r,color){const va=new T.Vector3(...a),vb=new T.Vector3(...b);const m=mesh(parent,cylinder,color,va.clone().add(vb).multiplyScalar(.5).toArray(),[r,va.distanceTo(vb),r]);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),vb.sub(va).normalize());return m;}
export class FlywayScene {
 constructor(canvas){this.canvas=canvas;this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.scene=new T.Scene();this.scene.background=new T.Color(0x78cceb);this.scene.fog=new T.Fog(0xa8dced,85,230);this.camera=new T.PerspectiveCamera(48,1,.1,350);this.camera.position.set(0,6.8,12.5);this.camera.lookAt(0,.8,-12);this.renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.07;this.scene.add(new T.HemisphereLight(0xd9f4ff,0x8582ab,1.85));const sun=new T.DirectionalLight(0xffe6b5,3.0);sun.position.set(-14,27,-20);sun.castShadow=true;sun.shadow.mapSize.set(1536,1536);Object.assign(sun.shadow.camera,{left:-24,right:24,top:26,bottom:-26,near:.5,far:75});sun.shadow.bias=-.0007;sun.shadow.normalBias=.07;sun.target.position.set(0,0,-15);this.scene.add(sun,sun.target);const rim=new T.DirectionalLight(0xbbe7ff,1.1);rim.position.set(8,8,8);this.scene.add(rim);this.objects=new Map();this.pool={sugar:[],block:[],hurdle:[],overhead:[]};this.particlePool=[];this.particles=[];this.elapsed=0;this.shake=0;this.swat=0;this.visualDistance=0;this.world=new Railway(this.scene);this.fly=this.makeFly();this.scene.add(this.fly);this.swatter=this.makeSwatter();this.scene.add(this.swatter);this.resize();this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(canvas.parentElement);}
 resize(){const r=this.canvas.getBoundingClientRect();if(r.width<1||r.height<1)return;this.renderer.setSize(r.width,r.height,false);this.camera.aspect=r.width/r.height;this.camera.fov=r.width/r.height<.8?59:48;this.camera.updateProjectionMatrix();}
 makeFly(){const g=new T.Group();const body=mesh(g,sphere,mat(0x304d40,.3,.4),[0,.97,.23],[.46,.48,.73]);mesh(g,sphere,mat(0x445d41,.32,.45),[0,1.12,-.37],[.47,.43,.45]);mesh(g,sphere,0x476f43,[0,1.03,-.65],[.35,.32,.26]);for(const s of [-1,1]){mesh(g,sphere,mat(0xd92657,.2,.22),[s*.37,1.21,-.52],[.3,.35,.32]);mesh(g,sphere,mat(0xff9dac,.16),[s*.5,1.37,-.66],[.075,.12,.045]);mesh(g,sphere,0xfff7dd,[s*.5,1.43,-.64],[.03,.055,.025]);rod(g,[s*.19,1.48,-.65],[s*.29,1.72,-.79],.023,0x172e27);mesh(g,sphere,0x152e26,[s*.29,1.72,-.79],[.05,.045,.04]);}for(let i=0;i<4;i++){const line=mesh(g,new T.TorusGeometry(.39,.018,5,32),0x1d352a,[0,.93,.28+i*.17],[1,1,1]);line.rotation.x=Math.PI/2;line.scale.set(1-i*.08,.95,1);}
 this.wings=[];const wingMat=new T.MeshPhysicalMaterial({color:0xe5fff1,transparent:true,opacity:.7,roughness:.25,metalness:.08,side:T.DoubleSide,depthWrite:false});for(const s of [-1,1]){const pivot=new T.Group();pivot.position.set(s*.17,1.42,.1);g.add(pivot);const wing=mesh(pivot,sphere,wingMat,[s*.61,0,.48],[.44,.037,.95]);wing.rotation.y=s*.6;wing.castShadow=false;for(let j=0;j<3;j++){const geometry=new T.BufferGeometry().setFromPoints([new T.Vector3(0,.044,0),new T.Vector3(s*(.2+j*.12),.045,.58),new T.Vector3(s*(.35+j*.23),.046,1.1)]);pivot.add(new T.Line(geometry,new T.LineBasicMaterial({color:0x78a899,transparent:true,opacity:.6})));}this.wings.push({pivot,side:s});}this.legs=[];for(const s of [-1,1])for(let i=0;i<3;i++){const leg=new T.Group();leg.position.set(s*.32,.95,(i-1)*.38);g.add(leg);const z=(i-1)*.26;rod(leg,[0,0,0],[s*.35,-.31,z],.033,0x1f3328);rod(leg,[s*.35,-.31,z],[s*.53,-.79,z+.17],.027,0x1f3328);const shoe=mesh(leg,sphere,0xe1fa71,[s*.55,-.81,z+.14],[.12,.082,.2]);this.legs.push({leg,side:s,index:i});}this.flyBody=body;return g;}
 makeSwatter(){const g=new T.Group();const pink=mat(colors.pink,.33);const edge=mat(0xce2a69,.36);for(const x of [-1.55,1.55])mesh(g,box,pink,[x,0,0],[.22,.19,3.4]);for(const z of [-1.7,1.7])mesh(g,box,pink,[0,0,z],[3.3,.19,.22]);for(let i=-5;i<=5;i++){mesh(g,box,pink,[i*.27,0,0],[.045,.065,3.2]);mesh(g,box,pink,[0,0,i*.29],[3,.065,.045]);}mesh(g,box,edge,[0,-.03,4.5],[.29,.21,5.6]);mesh(g,round,pink,[0,0,8.1],[.31,.9,.17]).rotation.x=Math.PI/2;mesh(g,new T.TorusGeometry(.19,.045,8,20),0xa72858,[0,0,8.65],[1,1,1]).rotation.x=Math.PI/2;return g;}
 makeObstacle(type,variant=0){return this.world.obstacle(type,variant);}
 makeSugar(){const g=new T.Group();mesh(g,box,mat(0xffe995,.35,.1),[0,.75,0],[.42,.42,.42]);const halo=mesh(g,new T.TorusGeometry(.38,.035,6,18),new T.MeshBasicMaterial({color:0xffec94}),[0,.75,0]);halo.castShadow=false;return g;}
 burst(x,z,color=0xffee85,count=9){for(let i=0;i<count;i++){const m=this.particlePool.pop()||mesh(this.scene,box,color);m.material=mat(color);m.position.set(x,.8,z);m.scale.setScalar(.09);this.scene.add(m);this.particles.push({mesh:m,vx:(Math.random()-.5)*5,vy:3+Math.random()*4,vz:(Math.random()-.5)*5,life:.65});}}
 hit(){this.shake=.5;this.swat=.8;this.burst(this.fly.position.x,0,0xf2548c,16);}
 reset(){for(const v of this.objects.values()){this.scene.remove(v);this.pool[v.userData.poolType].push(v);}this.objects.clear();for(const p of this.particles){this.scene.remove(p.mesh);this.particlePool.push(p.mesh);}this.particles=[];this.swat=0;this.shake=0;}
 update(run,dt,phase){this.elapsed+=dt;const t=this.elapsed;const isActive=phase==='running';const idle=phase==='ready';this.visualDistance=idle?this.visualDistance+dt*3:run.distance;this.world.update(this.visualDistance,t);
 const ids=new Set();for(const o of run.objects){ids.add(o.id);let m=this.objects.get(o.id);if(!m){m=this.pool[o.type].pop()||(o.kind==='sugar'?this.makeSugar():this.makeObstacle(o.type,o.id%3));m.userData.poolType=o.type;this.scene.add(m);this.objects.set(o.id,m);}m.position.set(LANES[o.lane],0,-(o.at-run.distance));m.visible=o.kind==='obstacle'?true:!o.done;if(o.kind==='sugar'){m.rotation.y=t*2.5+o.id;m.position.y=Math.sin(t*3+o.id)*.12;}}for(const [id,m]of this.objects){if(!ids.has(id)){this.scene.remove(m);this.pool[m.userData.poolType].push(m);this.objects.delete(id);}}
 const targetX=idle?2.05:run.x;this.fly.position.x=idle?this.fly.position.x+(targetX-this.fly.position.x)*(1-Math.exp(-8*dt)):run.x;this.fly.position.y=run.height+Math.sin(t*(isActive?28:5))*(isActive?.035:.035);this.fly.position.z=idle?1.1:0;const scale=idle?1.55:1.05;this.fly.scale.lerp(new T.Vector3(scale,scale*(run.duck>0?.58:1),scale),1-Math.exp(-9*dt));this.fly.rotation.y=idle?-.48:-(LANES[run.lane]-run.x)*.17;this.fly.rotation.z=isActive?clamp((LANES[run.lane]-run.x)*-.12,-.23,.23):Math.sin(t)*.03;this.fly.visible=!run.ended&&run.invincible>0?Math.floor(t*16)%3!==0:true;if(phase==='over'){this.fly.scale.y=.13;this.fly.position.y=-.02;}
 for(const {pivot,side}of this.wings){pivot.rotation.z=side*(Math.sin(t*(run.jump>0?95:70))*.23-.1);pivot.rotation.y=side*.13;}for(const {leg,side,index}of this.legs){const phase=t*(isActive?23:7)+index*2.3+side*2;leg.rotation.x=Math.sin(phase)*(isActive?.35:.06);leg.rotation.z=Math.cos(phase)*.09;}
 this.swat=Math.max(0,this.swat-dt);const slam=this.swat>0?Math.sin((1-this.swat/.8)*Math.PI):0;const end=phase==='over';const swX=idle?3.5:run.x*.5+2.8-run.hits*.8;this.swatter.position.x+=(swX-this.swatter.position.x)*(1-Math.exp(-4*dt));this.swatter.position.y=end?.18:5.9-run.hits*.72+Math.sin(t*2)*.22-slam*2;this.swatter.position.z=end?0:3.4-run.hits*.7;this.swatter.rotation.set(idle?-.32:-.25+slam*.4,Math.sin(t*.7)*.1,-.24+Math.sin(t*1.8)*.09);if(end)this.swatter.rotation.set(0,0,0);
 for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;p.vy-=dt*16;p.mesh.position.x+=p.vx*dt;p.mesh.position.y+=p.vy*dt;p.mesh.position.z+=p.vz*dt;p.mesh.rotation.x+=dt*5;p.mesh.rotation.z+=dt*7;p.mesh.scale.setScalar(Math.max(.001,.13*p.life));if(p.life<=0){this.scene.remove(p.mesh);this.particlePool.push(p.mesh);this.particles.splice(i,1);}}
 this.shake=Math.max(0,this.shake-dt);const shake=this.reduced?0:this.shake;this.camera.position.x=(idle?-.65:run.x*.12)+(Math.random()-.5)*shake*.4;this.camera.position.y=5.7+(Math.random()-.5)*shake*.3;this.camera.position.z=idle?12.4:11.8;this.camera.lookAt(idle?0:run.x*.1,1.3,-20);this.renderer.render(this.scene,this.camera);}
}


